const languageNames = { en:'English', fa:'فارسی', ar:'العربية', es:'Español' };
let activeLanguage = localStorage.getItem('tradejournal-language') || 'en';
let toastTimer;
function applyLanguage(language) {
  const copy = translations[language] || translations.en;
  activeLanguage = language;
  document.documentElement.lang = language;
  document.documentElement.dir = language === 'fa' || language === 'ar' ? 'rtl' : 'ltr';
  document.querySelectorAll('[data-i18n]').forEach((node) => { node.textContent = copy[node.dataset.i18n] || ''; });
  document.querySelectorAll('[data-i18n-placeholder]').forEach((node) => { node.placeholder = copy[node.dataset.i18nPlaceholder] || ''; });
  document.querySelector('#currentLanguage').textContent = languageNames[language];
  document.querySelectorAll('[data-language]').forEach((button) => button.classList.toggle('active', button.dataset.language === language));
  localStorage.setItem('tradejournal-language', language);
}
function showToast(message) { const toast = document.querySelector('#toast'); toast.textContent = message; toast.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), 2600); }
const languageButton = document.querySelector('#languageButton'); const languageMenu = document.querySelector('#languageMenu');
applyLanguage(activeLanguage);
languageButton.addEventListener('click', () => { const open = languageMenu.hidden; languageMenu.hidden = !open; languageButton.setAttribute('aria-expanded', String(open)); });
document.querySelectorAll('[data-language]').forEach((button) => button.addEventListener('click', () => { applyLanguage(button.dataset.language); languageMenu.hidden = true; languageButton.setAttribute('aria-expanded','false'); }));
document.addEventListener('click', (event) => { if (!event.target.closest('.language-picker')) { languageMenu.hidden = true; languageButton.setAttribute('aria-expanded','false'); } });
// Account-creation gate (fixed): a fresh browser (no tradejournal:dev-user-id yet) must name
// itself BEFORE a character selection is allowed to complete - clicking a character card opens
// the name step instead of proceeding immediately, and the pending selection only completes
// after a real account exists. A returning browser (id already stored) is unaffected - the
// card completes exactly as it always has. Creation goes through dev-user-switcher.js's own
// exported createUser() - the single place a user is ever created - so there is exactly one
// implementation of that API call, never a second one duplicated here.
const DEV_USER_ID_KEY = 'tradejournal:dev-user-id';
function hasDevUser() { try { return !!localStorage.getItem(DEV_USER_ID_KEY); } catch (_) { return false; } }

const nameStepOverlay = document.querySelector('#nameStepOverlay');
const nameStepInput = document.querySelector('#nameStepInput');
const nameStepSubmit = document.querySelector('#nameStepSubmit');
const nameStepError = document.querySelector('#nameStepError');
const nameStepClose = document.querySelector('#nameStepClose');
let pendingCharacterCard = null;

function completeCharacterSelection(card) {
  const character = card.dataset.character;
  document.querySelectorAll('.character-card').forEach((item) => item.classList.toggle('selected', item === card));
  const key = `${character}Name`;
  showToast((translations[activeLanguage].selected || '').replace('{character}', translations[activeLanguage][key]));
  window.setTimeout(() => window.parent.postMessage({ type: 'tradejournal:character-selected', character }, '*'), 220);
}

document.querySelectorAll('.select-character').forEach((button) => button.addEventListener('click', () => {
  const card = button.closest('.character-card');
  if (hasDevUser()) { completeCharacterSelection(card); return; }
  pendingCharacterCard = card;
  openNameStep();
}));

// The top "login" buttons stay a pure front-end demo action, as they always were - account
// creation is owned entirely by the character-selection gate above, not by these.
document.querySelectorAll('[data-action]').forEach((button) => button.addEventListener('click', () => showToast(translations[activeLanguage].demo)));

function openNameStep() {
  nameStepError.textContent = '';
  nameStepInput.value = '';
  nameStepOverlay.hidden = false;
  window.setTimeout(() => nameStepInput.focus(), 0);
}
function closeNameStep() { nameStepOverlay.hidden = true; pendingCharacterCard = null; }

// Distinguishes "the request never reached a server" (fetch itself rejects with a TypeError -
// almost always because the Community backend process isn't running, or is on the wrong port)
// from "a server responded but rejected the request" (createUser()'s Error carries the real
// server-side code as .message, e.g. VALIDATION_FAILED) - a bare "could not create" message
// with no distinction between those two was a dead end for diagnosing why every attempt failed.
function describeCreateError(error) {
  if (error instanceof TypeError) return translations[activeLanguage].nameStepErrorOffline;
  const base = translations[activeLanguage].nameStepError;
  return error && error.message ? `${base} (${error.message})` : base;
}

async function submitNameStep() {
  const name = nameStepInput.value.trim();
  if (!name) { nameStepInput.focus(); return; }
  nameStepSubmit.disabled = true;
  nameStepError.textContent = '';
  try {
    await window.TradeJournalDevUserSwitcher.createUser(name);
    const card = pendingCharacterCard;
    closeNameStep();
    if (card) completeCharacterSelection(card);
    else showToast(translations[activeLanguage].nameStepSuccess);
  } catch (error) {
    nameStepError.textContent = describeCreateError(error);
  } finally {
    nameStepSubmit.disabled = false;
  }
}
nameStepSubmit.addEventListener('click', submitNameStep);
nameStepInput.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); submitNameStep(); } });
nameStepClose.addEventListener('click', closeNameStep);
nameStepOverlay.addEventListener('click', (event) => { if (event.target === nameStepOverlay) closeNameStep(); });
